import{z as o,x as r,o as e,c as l,q as B,j as n,D as E,d as i,s,S as A}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"BSV 情绪模型","description":"","frontmatter":{"title":"BSV 情绪模型","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bsv-sentiment-model.md","filePath":"econ/bsv-sentiment-model.md","lastUpdated":1791413859000}'),p={name:"econ/bsv-sentiment-model.md"};function d(D,a,m,_,h,c){const t=r("Mermaid");return e(),l("div",null,[a[2]||(a[2]=B('<h1 id="bsv-情绪模型" tabindex="-1">BSV 情绪模型 <a class="header-anchor" href="#bsv-情绪模型" aria-label="Permalink to &quot;BSV 情绪模型&quot;">​</a></h1><div class="epigraph"><p>同一条盈余流，人有时当均值回复、有时当趋势；保守与代表性轮流上场，价格先反应不足再反应过度。</p><footer>—— Barberis, Shleifer and Vishny, A Model of Investor Sentiment, Journal of Financial Economics, 1998</footer></div><p><a href="/econ/limits-to-arbitrage">上一课</a>说明错定价可以活。本课缺口是方向与动态：盈余公告后的漂移（反应不足）与长期反转（反应过度）如何来自同一套判断。零件来自<a href="/econ/belief-updating-biases">信念更新</a>，此处放进价格。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>盈余的真实过程是随机游走（或弱自相关）。投资者不知道，在两个错误模型间切换：模型 M1 均值回复，模型 M2 趋势。看到延续，代表性启发式提高 M2 的后验；看到反转，提高 M1。保守主义让他们对单次公告调整不足。结果：公告后价格慢慢走完该走的（漂移），一串同号盈余后价格走过头（过度），随后反转。缺口是把启发式写成过滤问题，而不是再写 SV 的赎回。</p><p><span class="marginnote">术语翻译：这里的「保守主义」不是性格稳重的意思，而是信念更新打折扣——新证据暗示该挪多少，人只挪一部分。一次盈余超预期，价格只挪到一半，剩下的一半在随后数周慢慢补齐，这就是「公告后漂移」。</span></p><p><span class="marginnote">BSV 的投资者是代表性的行为主体，不是噪声的随机需求。情绪在此是对体制的错误信念，可预测。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>离散盈余 \\(\\pm\\)，隐马尔可夫式的错误模型切换，价格等于行为主体的贴现期望。套利者不进入或进入有限（承接 SV）。预测：短期动量/PEAD，长期反转，与盈余序列的路径依赖。本课不估计公告窗口。量化栏的事件研究是测量，本课是机制。</p>',9)),(e(),n(A,null,{default:E(()=>[s(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20HEU%5B%22%E4%BF%9D%E5%AE%88%20%2B%20%E4%BB%A3%E8%A1%A8%E6%80%A7%22%5D%20--%3E%20FIL%5B%22%E5%9C%A8%E5%9D%87%E5%80%BC%E5%9B%9E%E5%A4%8D%E4%B8%8E%E8%B6%8B%E5%8A%BF%E9%97%B4%E5%88%87%E6%8D%A2%22%5D%0A%20%20FIL%20--%3E%20UNDER%5B%22%E5%8D%95%E6%AC%A1%E5%85%AC%E5%91%8A%3A%20%E5%8F%8D%E5%BA%94%E4%B8%8D%E8%B6%B3%2C%20%E6%BC%82%E7%A7%BB%22%5D%0A%20%20FIL%20--%3E%20OVER%5B%22%E5%90%8C%E5%8F%B7%E5%BA%8F%E5%88%97%3A%20%E5%8F%8D%E5%BA%94%E8%BF%87%E5%BA%A6%2C%20%E5%8F%8D%E8%BD%AC%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是错误的体制学习。真实无体制，人以为有。似然在短样本里被代表性夸大，单次新息又被保守压住——两个偏差的时间尺度不同，于是同一模型先不足后过度。这与 DSSW 外生噪声不同：这里错定价的符号可由盈余路径预测。套利限制决定预测能否被交易吃掉。</p><p>与 <a href="/econ/emh">EMH</a> 联合假说：用 CAPM 调过的 alpha 可以来自错误期望，也可以来自错误 \\(m\\)。BSV 明确走期望侧。</p><p>真实过程若是随机游走，最优是忽略「趋势还是回复」的叙事。行为主体没有这条知识，用代表性把短序列当成体制证据，又用保守把单次公告的似然乘得不够。两个偏差的频率不同：一次公告 → 漂移；一串同号 → 走过头。套利者若受 SV 约束，预测可以有价格。本课不把 PEAD 的估计窗口写进来，那是测量；机制是错误过滤。</p><p><span class="marginnote">直觉类比：连赢三把就觉得「手感来了」，是把短样本当长期规律（代表性）。赌桌上它让你加注；在 BSV 里它让投资者抬高「趋势模型」的权重，把价格推过基本面。</span></p><p><span class="marginnote">数字实例：设一次超预期本应让价格上调 10 元。保守的投资者第一次只挪 4 元，余下 6 元靠公告后慢慢补齐（漂移）；若接着再来几次同号盈余，代表性把预期抬到 15 元，多出的 5 元日后就得跌回来（反转）。</span></p>',6)),(e(),n(A,null,{default:E(()=>[s(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20E1%5B%22%E5%8D%95%E6%AC%A1%E7%9B%88%E4%BD%99%E8%B6%85%E9%A2%84%E6%9C%9F%22%5D%20--%3E%20C%5B%22%E4%BF%9D%E5%AE%88%3A%20%E5%8F%AA%E8%B0%83%E6%95%B4%E4%B8%80%E9%83%A8%E5%88%86%22%5D%0A%20%20C%20--%3E%20DR%5B%22%E4%BB%B7%E6%A0%BC%E6%85%A2%E5%8D%8A%E6%8B%8D%2C%20%E5%85%AC%E5%91%8A%E5%90%8E%E7%BB%A7%E7%BB%AD%E4%B8%8A%E6%BC%82%22%5D%0A%20%20E2%5B%22%E7%9B%88%E4%BD%99%E8%BF%9E%E7%BB%AD%E5%90%8C%E5%8F%B7%22%5D%20--%3E%20R%5B%22%E4%BB%A3%E8%A1%A8%E6%80%A7%3A%20%E6%8A%AC%E9%AB%98%E8%B6%8B%E5%8A%BF%E6%A8%A1%E5%9E%8B%E6%9D%83%E9%87%8D%22%5D%0A%20%20R%20--%3E%20OVER%5B%22%E4%BB%B7%E6%A0%BC%E6%8E%A8%E8%BF%87%E5%9F%BA%E6%9C%AC%E9%9D%A2%22%5D%0A%20%20OVER%20--%3E%20REV%5B%22%E7%9B%88%E4%BD%99%E6%98%BE%E5%87%BA%E9%9A%8F%E6%9C%BA%E6%B8%B8%E8%B5%B0%E6%9C%AC%E8%89%B2%2C%20%E4%BB%B7%E6%A0%BC%E5%9B%9E%E8%90%BD%E5%8F%8D%E8%BD%AC%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=B('<p>这张图回答的是：一轮完整周期里，两个偏差如何接力。时间尺度是关键——保守管「单次公告的当下」（反应不足），代表性管「一串同号之后的远期」（反应过度），同一批投资者因此既制造动量又制造反转。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>真实盈余过程若本就有体制切换，部分「过度」可以是理性学习。BSV 选择随机游走当对照，为的是把偏差衬出来。本课不声称现场盈余是随机游走。DHS 用过度自信讲另一条不足–过度的路，下一课对照，不在此合并。</p><p>后课默认：投资者情绪可以是对序列的错误体制信念；过度自信模型改的是信号精度，不是体制切换。</p><p>真实若是随机游走，最优是忽略趋势叙事；行为主体在两个错误体制间切换。</p><p>一次公告偏保守故漂移，一串同号偏代表性故走过头。方向来自盈余路径。</p><p><span class="marginnote">现场盈余不必真是随机游走；该假设是为了把偏差衬出来。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BSV：保守造成漂移，代表性造成长期过度与反转。</li><li>方向来自盈余路径，存活来自上一课的套利限制。</li><li>不重写启发式定义，只把它放进价格。</li><li>情绪在此是对体制的错误信念，可预测。</li><li>PEAD 窗口是测量，本课只给过滤机制。</li><li>出处：Barberis, Shleifer and Vishny, <em>JFE</em> 1998。</li></ul>',9))])}const f=o(p,[["render",d]]);export{S as __pageData,f as default};
